def make(slug, title, date, ref, sample, product_type, params, notes=''):
    d = Document()
    s = d.sections[0]
    s.top_margin = Inches(.75); s.bottom_margin = Inches(.75)
    s.left_margin = Inches(.85); s.right_margin = Inches(.85)
    normal = d.styles['Normal']; normal.font.name = 'Arial'; normal.font.size = Pt(10.5)
    normal.paragraph_format.space_after = Pt(6)
    p = d.add_paragraph(style='Title')
    r = p.add_run(title); r.font.name = 'Arial'; r.font.size = Pt(20); r.font.bold = True; r.font.color.rgb = RGBColor(0,0,0)
    p = d.add_paragraph(); p.paragraph_format.space_after = Pt(12)
    r = p.add_run('Extracto técnico de solicitudes históricas'); r.italic = True; r.font.size = Pt(9)
    for label, value in [('Fecha de solicitud: ', date), ('Carta(s) fuente: ', ref), ('Muestra(s) / lote(s): ', sample), ('Tipo indicado en la carta: ', product_type)]:
        p = d.add_paragraph(); p.add_run(label).bold = True; p.add_run(value)
    p = d.add_paragraph(); p.paragraph_format.space_before = Pt(8); p.add_run('Parámetros solicitados').bold = True
    d.add_paragraph(params)
    if notes:
        p = d.add_paragraph(); p.add_run('Observación documental: ').bold = True; p.add_run(notes)
    d.save(OUT / f'Solicitud_Tecnica_{slug}.docx')

